0, \"showMaxSize\": false, \"documentType\": \"\", \"errorMessage\": {\"text\": \"\"}, \"showMimeList\": false}','[{\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"label.text\", \"path\": \"label.text\", \"type\": \"text\", \"label\": \"Label Text\"}, {\"key\": \"label.classes\", \"path\": \"label.classes\", \"type\": \"select\", \"label\": \"Label Classes\", \"options\": [{\"label\": \"Medium (m)\", \"value\": \"govuk-label--m\"}, {\"label\": \"Small (s)\", \"value\": \"govuk-label--s\"}, {\"label\": \"Large (l)\", \"value\": \"govuk-label--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-label--xl\"}, {\"label\": \"Visually Hidden\", \"value\": \"govuk-visually-hidden\"}, {\"label\": \"None\", \"value\": \"\"}]}, {\"key\": \"hint.text\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"multiple\", \"path\": \"multiple\", \"type\": \"select\", \"label\": \"Allow Multiple?\", \"options\": [{\"label\": \"No\", \"value\": false}, {\"label\": \"Yes\", \"value\": true}]}, {\"key\": \"maxSizeMb\", \"path\": \"maxSizeMb\", \"type\": \"number\", \"label\": \"Max Size (MB)\"}, {\"key\": \"accept\", \"path\": \"accept\", \"type\": \"text\", \"label\": \"Accept (MIME list)\"}, {\"key\": \"showMimeList\", \"path\": \"showMimeList\", \"type\": \"select\", \"label\": \"Show MIME List?\", \"options\": [{\"label\": \"Yes\", \"value\": true}, {\"label\": \"No\", \"value\": false}]}, {\"key\": \"showMaxSize\", \"path\": \"showMaxSize\", \"type\": \"select\", \"label\": \"Show Max Size?\", \"options\": [{\"label\": \"Yes\", \"value\": true}, {\"label\": \"No\", \"value\": false}]}, {\"key\": \"documentType\", \"path\": \"documentType\", \"type\": \"text\", \"label\": \"Document Type (metadata)\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"text\", \"label\": \"CSS Classes\"}, {\"key\": \"formGroup.classes\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}, {\"key\": \"disabled\", \"path\": \"disabled\", \"type\": \"select\", \"label\": \"Disabled?\", \"options\": [{\"label\": \"False\", \"value\": false}, {\"label\": \"True\", \"value\": true}]}]','{% set theId = props.id or props.name %}\n{% set labelObj = props.label %}\n{% set hintObj = props.hint %}\n{% set sizeMb = props.maxSizeMb or 10 %}\n{% set types = props.accept or \'.pdf,.jpg,.jpeg,.png,.gif,.heic\' %}\n<div class=\"govuk-form-group {{ props.formGroup.classes }}\">\n  {% if labelObj %}\n  <label class=\"govuk-label {{ labelObj.classes }}\" for=\"{{ theId }}\">{{ labelObj.text }}</label>\n  {% endif %}\n  {% if hintObj and hintObj.text %}<div class=\"govuk-hint\">{{ hintObj.text }}</div>{% endif %}\n  <input class=\"govuk-file-upload {{ props.classes }}\" id=\"{{ theId }}\" name=\"{{ props.name }}\" type=\"file\"{% if props.multiple %} multiple{% endif %}{% if props.accept %} accept=\"{{ props.accept }}\"{% endif %}{% if props.documentType %} data-document-type=\"{{ props.documentType }}\"{% endif %}{% if props.maxSizeMb is defined %} data-max-size-mb=\"{{ props.maxSizeMb }}\"{% endif %}{% if props.disabled %} disabled{% endif %}>\n  {% if props.showMimeList %}<div class=\"govuk-hint\">Allowed types: {{ types }}</div>{% endif %}\n  {% if props.showMaxSize %}<div class=\"govuk-hint\">Max size: {{ sizeMb }}MB.</div>{% endif %}\n</div>','active','2025-03-27 17:03:12','2025-09-15 09:47:26',0,'null'),(20,'warning-text',1,'warning-text','Warning Text','GOV.UK styled warning callout box with icon.','{\"id\": \"\", \"name\": \"warning-text\", \"role\": \"alert\", \"text\": {\"en\": \"Important: action required.\", \"fr\": \"Important : action requise.\"}, \"classes\": \"\", \"iconFallbackText\": {\"en\": \"Warning\", \"fr\": \"Avertissement\"}}','[{\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"la